begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(7);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into agencies(id,name,agency_code,state_code,status) values('a3100000-0000-0000-0000-000000000001','Operator test','OPTEST-MO','MO','pending');
insert into auth.users(id,email) values('d3100000-0000-0000-0000-000000000001','optest-admin@example.invalid'),('d3100000-0000-0000-0000-000000000002','optest-operator@example.invalid');
update profiles set must_change_password=false,active=true where id in ('d3100000-0000-0000-0000-000000000001','d3100000-0000-0000-0000-000000000002');
update profiles set platform_admin=true where id='d3100000-0000-0000-0000-000000000002';
insert into memberships(agency_id,user_id,role,role_key) values('a3100000-0000-0000-0000-000000000001','d3100000-0000-0000-0000-000000000001','administrator','administrator');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"d3100000-0000-0000-0000-000000000001"}',true);
select throws_ok($$select operator_transition_agency('a3100000-0000-0000-0000-000000000001','active','Review','pending')$$,'42501','Operator access required.','agency administrator cannot review');
select is((select count(*)::int from operator_agency_lifecycle),0,'agency roles cannot read operator lifecycle');
select throws_ok($$update agencies set status='active' where id='a3100000-0000-0000-0000-000000000001'$$,'42501',null,'direct status updates are denied');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"d3100000-0000-0000-0000-000000000002"}',true);
select throws_ok($$select operator_transition_agency('a3100000-0000-0000-0000-000000000001','active',' ','pending')$$,'P0001','Add a reason of at most 1000 characters.','reason required');
select lives_ok($$select operator_transition_agency('a3100000-0000-0000-0000-000000000001','active','Verified','pending')$$,'operator approves');
select is((select actor_id from operator_agency_lifecycle where agency_id='a3100000-0000-0000-0000-000000000001'),'d3100000-0000-0000-0000-000000000002'::uuid,'real caller attributed');
select throws_ok($$select operator_transition_agency('a3100000-0000-0000-0000-000000000001','rejected','Stale','pending')$$,'P0001','Agency changed. Refresh and try again.','stale state rejected');
select * from finish();
rollback;
